float drawBox(vec2 _st, vec2 _size) {
    vec2 halfSize = vec2(0.5) - _size * 0.5;
    vec2 smoothEdge = vec2(0.001);
    vec2 uv = smoothstep(halfSize, halfSize + smoothEdge, _st);
    uv *= smoothstep(halfSize, halfSize + smoothEdge, vec2(1.0) - _st);
    return uv.x * uv.y;
}

void mainImage(out vec4 fragColor, in vec2 fragCoord)
{
    vec2 st = (2.0 * fragCoord - iResolution.xy) / iResolution.y;

    vec3 cell_color = vec3(1.0, 1.0, 1.0);
    vec3 line_color = vec3(0.0, 0.0, 0.0);
    st *= 2.0;
    st = fract(st);

    vec3 color = mix(line_color, cell_color, drawBox(st, vec2(0.85)));

    fragColor = vec4(color, 1.0f);
}
